function switchAdjectives(sentence) {
  const words = sentence.split(" ");
  const adjectives = words.filter(word => word === "beautiful" || word === "green");
  const reversedAdjectives = adjectives.reverse();
  const updatedSentence = reversedAdjectives.join(" ") + " " + words.join(" ");
  return updatedSentence;
}

