// Recursive function to generate the Fibonacci sequence
int fibonacci(int n, int a, int b) {
    if (n == 0) {
        return a;
    } else {
        return fibonacci(n - 1, b, a + b);
    }
}

int main() {
    int first_num, second_num, num_elements;

    // Prompt the user to input the first two integers and the number of sequence elements
    std::cout << "Enter the first two integers: ";
