    // Prompt the user to enter the number of sequence elements
    std::cout << "Enter the number of sequence elements to generate: ";
    std::cin >> num_elements;

    // Validate the inputs
    if (first_num < 0 || second_num < 0 || num_elements <= 0) {
        std::cout << "Invalid input. Please enter non-negative integers.\n";
        return 1;
    }

    // Generate the Fibonacci sequence
    int sequence[num_elements];
    sequence[0] = first_num;
    sequence[1] = second_num;
    for (int i = 2; i < num_elements; i++) {
        sequence[i] = fibonacci(i - 2, sequence[i - 2], sequence[i - 1]);
    }

    // Output the generated sequence
    std::cout << "Fibonacci sequence: ";
    for (int i = 0; i < num_elements; i++) {
        std::cout << sequence[i] << ", ";
    }
    std::cout << "\n";

    return 0;
}
```

