To solve this problem, you can use Swift's Natural Language framework to analyze the passage and identify homophones. Here's a step-by-step guide on how to create a Swift program to correct the homophones in the given passage:

1. Import the necessary frameworks:

```swift
import Foundation
import NaturalLanguage
```

2. Create a function to check if a word is a homophone of another word:

```swift
func isHomophone(word1: String, word2: String) -> Bool {
    let tagger = NLTagger(tagSchemes: [.lexicalClass])
    tagger.string = word1
    var tag1: String?
    tagger.enumerateTags(in: word1.startIndex..<word1.endIndex, unit: .word, scheme: .lexicalClass) { tag, range in
        tag1 = tag
    }

    tagger.string = word2
    var tag2: String?
    tagger.enumerateTags(in: word2.startIndex..<word2.endIndex, unit: .word, scheme: .lexicalClass) { tag, range in
        tag2 = tag
    }

    return tag1 == tag2
}
```

3. Create a function to replace homophones in a passage:

```swift
func replaceHomophones(passage: String) -> String {
    let words = passage.components(separatedBy: .whitespacesAndNewlines)
    var correctedPassage = ""

    for word in words {
        let possibleHomophones = ["their", "there", "they're"]
        for homophone in possibleHomophones {
            if isHomophone(word: word, word2: homophone) {
                correctedPassage += homophone + " "
            } else {
                correctedPassage += word + " "
            }
        }
    }

    return correctedPassage
}
```

