func main() {
	sourceFile := "example.go"
	structName := "MyStruct"

	content, err := ioutil.ReadFile(sourceFile)
	if err != nil {
		log.Fatal(err)
	}

	// Extract the struct definition from the Go source file
	structDefinition := extractStructDefinition(string(content), structName)
	if structDefinition == "" {
		log.Fatalf("Could not find struct %s in %s", structName, sourceFile)
	}

	// Generate the Avro schema
	schema, err := generateAvroSchema(structDefinition)
	if err != nil {
		log.Fatal(err)
	}

	// Write the Avro schema to a file
	err = ioutil.WriteFile("struct.avsc", []byte(schema), 0644)
	if err != nil {
		log.Fatal(err)
	}
}

func extractStructDefinition(content string, structName string) string {
	lines := strings.Split(content, "\n")

	for _, line := range lines {
