Here's a C function that converts an array of pointers (argv) to a single null-terminated string:

```c
#include <stdio.h>
#include <stdlib.h>

char *argv_to_str(int argc, char **argv) {
    int i;
    size_t len = 0;

    for (i = 0; i < argc; i++) {
        len += strlen(argv[i]) + 1; // add space for the null terminator
    }

    char *str = malloc(len);
    if (str == NULL) {
        return NULL;
    }

    i = 0;
    while (i < argc) {
        strncpy(str, argv[i], strlen(argv[i]));
        str += strlen(argv[i]);
        i++;
    }

    *str = '\0';
    return str;
}

int main(int argc, char **argv) {
    char *str = argv_to_str(argc, argv);
    if (str != NULL) {
        printf("Converted string: %s\n", str);
        free(str);
    } else {
        printf("Error converting argv to string.\n");
    }

    return 0;
}
```

