To create a simple toast notification using React context, follow these steps:

1. Create a `ToastContext` file:

```javascript
import React, { createContext, useState } from 'react';

const ToastContext = createContext();

function ToastProvider({ children }) {
  const [toastMessages, setToastMessages] = useState([]);

  function addToastMessage(message) {
    setToastMessages((prevMessages) => [...prevMessages, message]);
  }

  return (
    <ToastContext.Provider value={{ addToastMessage }}>
      {children}
    </ToastContext.Provider>
  );
}

export { ToastContext, ToastProvider };
```

2. Create a `Toast` component:

```javascript
import React, { useContext } from 'react';
import { ToastContext } from './ToastContext';

function Toast() {
  const { addToastMessage } = useContext(ToastContext);

  function handleClick() {
    addToastMessage('Toast message!');
  }

  return (
    <button onClick={handleClick}>Show Toast</button>
  );
}

export default Toast;
```

3. Use the `Toast` component in your app:

```javascript
import React from 'react';
import Toast from './Toast';

function App() {
  return (
    <div>
      <Toast />
    </div>
  );
}

export default App;
```

Now, when you click the "Show Toast" button, a toast message will be added to the list of messages and displayed.

