    { id: 3, name: 'Bob Johnson', email: 'bobjohnson@example.com' },
  ];

  return new Promise((resolve) => {
    setTimeout(() => {
      resolve(emails.filter((email) => email.email.startsWith(prefix)));
    }, 500);
  });
};

const EmailInputField = () => {
  const {
    isOpen,
    selectedItem,
    getMenuProps,
    getInputProps,
    getComboboxProps,
    highlightedIndex,
