Here's a simple React utility to remove widows. This component will check if there are any words that are wider than the container width and adjust the font size accordingly.

```jsx
import React, { useRef, useState } from 'react';

const RemoveWidows = ({ children }) => {
  const containerRef = useRef(null);
  const [fontSize, setFontSize] = useState(16);

  const handleResize = () => {
    const containerWidth = containerRef.current.offsetWidth;
    const words = children.split(' ');
    let adjustedFontSize = fontSize;

    words.forEach((word) => {
      const wordWidth = word.getBoundingClientRect().width;

      if (wordWidth > containerWidth) {
        adjustedFontSize -= 2;
      }
    });

    setFontSize(adjustedFontSize);
  };

  return (
    <div ref={containerRef} onResize={handleResize}>
      <p style={{ fontSize }}>{children}</p>
    </div>
  );
};

export default RemoveWidows;
```

