import React, { useState } from 'react';

const ManageRegistrationScreen = () => {
  const [registrations, setRegistrations] = useState([]);

  async function checkMNPStatusAPI(phoneNo, index) {
    console.log('mnpphoneNo: ', phoneNo);

    var headers = new Headers();
    headers.append('Authorization', 'Bearer ' + user.getAccessToken());

    const response = await fetch(api.checkPortInStatus(user.getProductCode(), phoneNo), {
