    const rjson = await response.json();
    setRegistrations((prevRegistrations) => prevRegistrations.map((registration, i) => {
      if (index === i) {
        return { ...registration, mnpStatus: rjson.status };
      }
      return registration;
    }));
  }

  // Example usage:
  const examplePhoneNumbers = ['1234567890', '0987654321'];
  const promises = examplePhoneNumbers.map((phoneNumber, index) => checkMNPStatusAPI(phoneNumber, index));
  Promise.all(promises).then(() => console.log('All MNP statuses updated.'));
};

export default ManageRegistrationScreen;
```

