Here's a PowerShell script that recursively checks folders to see if their ACLs refer to SIDs which occur only in the SIDHistory of any user or group in the domain:

```powershell
# Define the function to check if an SID is in the SIDHistory of any user or group in the domain
function CheckSIDInSIDHistory($sid) {
    $domain = (Get-ADDomain).Name
    $users = Get-ADUser -Filter {(SID -eq $sid)} -Properties MemberOf
    $groups = Get-ADGroup -Filter {(SID -eq $sid)} -Properties MemberOf

    foreach ($user in $users) {
        if ($user.MemberOf -contains $domain) {
            return True
        }
    }

    foreach ($group in $groups) {
        if ($group.MemberOf -contains $domain) {
            return True
        }
    }

    return False
}

# Define the function to recursively check the ACLs of a folder and its subfolders
function CheckFolderACLs($folderPath) {
    $acl = (Get-Acl -Path $folderPath).Access
    $subfolders = Get-ChildItem -Path $folderPath -Directory

    foreach ($subfolder in $subfolders) {
        CheckFolderACLs($subfolder.FullName)
    }

    foreach ($access in $acl) {
        if ($access.IdentityReference -match '^S-1-5-21-') {
            $sid = New-Object System.Security.Principal.SecurityIdentifier($access.IdentityReference)
            if (CheckSIDInSIDHistory($sid)) {
                Write-Host "The ACL of $folderPath contains an SID that occurs only in the SIDHistory of a user or group in the domain."
            }
        }
    }
}

# Define the main function
function Main() {
    $folderPath = "C:\Your_Folder_Path"
    CheckFolderACLs($folderPath)
}

Main()
```

